$admin_title='Menu Principal'; include __DIR__.'/includes/header.php'; $msg='';$erro='';$edit=isset($_GET['edit'])&&$pdo?db_one($pdo,'SELECT * FROM menu_itens WHERE id=?',[(int)$_GET['edit']]):null;
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){$id=(int)($_POST['id']??0);$titulo=trim($_POST['titulo']??'');$url=trim($_POST['url']??'#');$parent=(int)($_POST['parent_id']??0);$ordem=max(0,(int)($_POST['ordem']??0));$status=isset($_POST['status'])?1:0;if(!verify_csrf($_POST['csrf_token']??null))$erro='Token de segurança inválido.';elseif($titulo==='')$erro='Informe o título do item.';elseif($id&&$parent===$id)$erro='Um item não pode ser pai dele mesmo.';else{if($id)$pdo->prepare('UPDATE menu_itens SET titulo=?,url=?,parent_id=?,ordem=?,status=? WHERE id=?')->execute([$titulo,$url,$parent?:null,$ordem,$status,$id]);else$pdo->prepare('INSERT INTO menu_itens(titulo,url,parent_id,ordem,status) VALUES(?,?,?,?,?)')->execute([$titulo,$url,$parent?:null,$ordem,$status]);$msg='Item de menu salvo.';$edit=null;}}
if(isset($_GET['delete'])&&$pdo&&verify_csrf($_GET['token']??null)){$pdo->prepare('DELETE FROM menu_itens WHERE id=?')->execute([(int)$_GET['delete']]);$msg='Item excluído.';}$items=$pdo?db_rows($pdo,'SELECT * FROM menu_itens ORDER BY ordem,id'):[];$parents=array_filter($items,fn($item)=>empty($item['parent_id']));
?><main class="admin-content"><div class="admin-heading"><div><h1>Menu principal</h1><p class="muted">Organize links, ordem e submenus da navegação pública.</p></div><a class="btn btn-primary" href="?novo=1">+ Novo item</a></div><?php if($msg): ?><div class="notice success"><?= e($msg) ?></div><?php endif; ?><?php if($erro): ?><div class="notice error"><?= e($erro) ?></div><?php endif; ?><div class="admin-panel"><?php if($edit||isset($_GET['novo'])): ?><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Nome do item<input name="titulo" required value="<?= e($edit['titulo']??'') ?>"></label><label>URL ou âncora<input name="url" required value="<?= e($edit['url']??'#') ?>" placeholder="pagina.php?slug=sobre ou #sobre"></label><label>Item pai<select name="parent_id"><option value="0">Item principal</option><?php foreach($parents as $parent): if((int)$parent['id']!==(int)($edit['id']??0)): ?><option value="<?= (int)$parent['id'] ?>" <?= ((int)($edit['parent_id']??0)===(int)$parent['id'])?'selected':'' ?>><?= e($parent['titulo']) ?></option><?php endif; endforeach; ?></select></label><label>Ordem<input type="number" name="ordem" min="0" value="<?= (int)($edit['ordem']??0) ?>"><small class="muted">Menor número aparece primeiro.</small></label><label class="check-row"><input type="checkbox" name="status" value="1" <?= (($edit['status']??1)?'checked':'') ?>> Item visível</label><div><button class="btn btn-primary">Salvar item</button> <a class="btn btn-outline" href="menu.php">Cancelar</a></div></form><?php else: ?><table class="admin-table"><thead><tr><th>Ordem</th><th>Item</th><th>URL</th><th>Hierarquia</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= (int)$item['ordem'] ?></td><td><?= $item['parent_id']?'↳ ':'' ?><strong><?= e($item['titulo']) ?></strong></td><td><?= e($item['url']) ?></td><td><?= $item['parent_id']?'Submenu':'Principal' ?></td><td><?= $item['status']?'Visível':'Oculto' ?></td><td><a href="?edit=<?= (int)$item['id'] ?>">Editar</a> &nbsp; <a href="?delete=<?= (int)$item['id'] ?>&token=<?= e(csrf_token()) ?>" onclick="return confirm('Excluir este item e seus subitens?')">Excluir</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></main><?php include __DIR__.'/includes/footer.php'; ?>
